-- Owner 2026-11-04: "ทำเลย ราคาเหมือน sms" — import Fuji Eurotech 2024 (bought via KC) as an extruder.
-- Source docs/catalogs/fuji/fuji-eurotech-2024.json (kg/m, dims read from the catalogue). Prices = SMS shop rates per colour
-- (170 THB/kg, wood grain 350). Pictures uploaded first to estimation-images/<tenant>/profiles/<id>.png with t = wall.
-- Ids are fixed (uuid5) so the file can be re-checked; it refuses to run twice.
BEGIN;
DO $$ BEGIN IF EXISTS (SELECT 1 FROM alu_providers WHERE tenant_id = '1b9affc4-2136-4ed1-b168-a36e6624e743' AND (id = '74148e3e-1944-5b93-81fa-c92f8414629b' OR short_name = 'FUJI')) THEN RAISE EXCEPTION 'Fuji already imported'; END IF; END $$;
DO $$ DECLARE a int; b int; c int; d int; e int; f int; BEGIN
  SELECT count(*) INTO a FROM alu_series WHERE provider_id = '74148e3e-1944-5b93-81fa-c92f8414629b';
  SELECT count(*) INTO b FROM alu_profiles WHERE provider_id = '74148e3e-1944-5b93-81fa-c92f8414629b';
  SELECT count(*) INTO c FROM alu_series_profiles sp JOIN alu_series s ON s.id = sp.series_id WHERE s.provider_id = '74148e3e-1944-5b93-81fa-c92f8414629b';
  SELECT count(*) INTO d FROM alu_series_types st JOIN alu_series s ON s.id = st.series_id WHERE s.provider_id = '74148e3e-1944-5b93-81fa-c92f8414629b';
  SELECT count(*) INTO e FROM alu_kg_prices WHERE provider_id = '74148e3e-1944-5b93-81fa-c92f8414629b';
  SELECT count(*) INTO f FROM alu_profiles WHERE provider_id = '74148e3e-1944-5b93-81fa-c92f8414629b' AND image_path IS NOT NULL;
  IF a <> 5 OR b <> 107 OR c <> 107 OR d <> 13 OR e <> 7 OR f <> 106 THEN
    RAISE EXCEPTION 'count mismatch: series % profiles % links % types % prices % images %', a, b, c, d, e, f; END IF;
  RAISE NOTICE 'OK series % profiles % links % types % prices % images %', a, b, c, d, e, f;
END $$;
SELECT s.name series, f.name family, (SELECT count(*) FROM alu_series_profiles sp WHERE sp.series_id = s.id) profiles, (SELECT string_agg(t.name, ' | ') FROM alu_series_types st JOIN door_window_types t ON t.id = st.type_id WHERE st.series_id = s.id) types FROM alu_series s JOIN alu_series_families f ON f.id = s.series_family_id WHERE s.provider_id = '74148e3e-1944-5b93-81fa-c92f8414629b' ORDER BY f.sort_order, s.name;
COMMIT;
